   233→// MustDelete removes any existing value for key from the trie. This function
   234→// will omit any encountered error but just print out an error message.
   235→func (t *StateTrie) MustDelete(key []byte) {
   236→	hk := crypto.Keccak256(key)
   237→	if t.preimages != nil {
   238→		delete(t.secKeyCache, common.Hash(hk))
   239→	}
   240→	t.trie.MustDelete(hk)
   241→}
   242→
   243→// DeleteStorage removes any existing storage slot from the trie.
   244→// If the specified trie node is not in the trie, nothing will be changed.
   245→// If a node is not found in the database, a MissingNodeError is returned.
   246→func (t *StateTrie) DeleteStorage(_ common.Address, key []byte) error {
   247→	hk := crypto.Keccak256(key)
   248→	if t.preimages != nil {
   249→		delete(t.secKeyCache, common.Hash(hk))
   250→	}
   251→	return t.trie.Delete(hk)
   252→}
   253→
   254→// DeleteAccount abstracts an account deletion from the trie.
   255→func (t *StateTrie) DeleteAccount(address common.Address) error {
   256→	hk := crypto.Keccak256(address.Bytes())
   257→	if t.preimages != nil {
   258→		delete(t.secKeyCache, common.Hash(hk))
   259→	}
   260→	return t.trie.Delete(hk)
   261→}
