   263→// GetKey returns the sha3 preimage of a hashed key that was
   264→// previously used to store a value.
   265→func (t *StateTrie) GetKey(shaKey []byte) []byte {
   266→	if t.preimages == nil {
   267→		return nil
   268→	}
   269→	if key, ok := t.secKeyCache[common.BytesToHash(shaKey)]; ok {
   270→		return key
   271→	}
   272→	return t.preimages.Preimage(common.BytesToHash(shaKey))
   273→}
   274→
   275→// Witness returns a set containing all trie nodes that have been accessed.
   276→func (t *StateTrie) Witness() map[string][]byte {
   277→	return t.trie.Witness()
   278→}
