   280→// Commit collects all dirty nodes in the trie and replaces them with the
   281→// corresponding node hash. All collected nodes (including dirty leaves if
   282→// collectLeaf is true) will be encapsulated into a nodeset for return.
   283→// The returned nodeset can be nil if the trie is clean (nothing to commit).
   284→// All cached preimages will be also flushed if preimages recording is enabled.
   285→// Once the trie is committed, it's not usable anymore. A new trie must
   286→// be created with new root and updated trie database for following usage
   287→func (t *StateTrie) Commit(collectLeaf bool) (common.Hash, *trienode.NodeSet) {
   288→	// Write all the pre-images to the actual disk database
   289→	if len(t.secKeyCache) > 0 {
   290→		if t.preimages != nil {
   291→			t.preimages.InsertPreimage(t.secKeyCache)
   292→		}
   293→		clear(t.secKeyCache)
   294→	}
   295→	// Commit the trie and return its modified nodeset.
   296→	return t.trie.Commit(collectLeaf)
   297→}
