   357→func (t *Trie) update(key, value []byte) error {
   358→	t.unhashed++
   359→	t.uncommitted++
   360→	k := keybytesToHex(key)
   361→	if len(value) != 0 {
   362→		_, n, err := t.insert(t.root, nil, k, valueNode(value))
   363→		if err != nil {
   364→			return err
   365→		}
   366→		t.root = n
   367→	} else {
   368→		_, n, err := t.delete(t.root, nil, k)
   369→		if err != nil {
   370→			return err
   371→		}
   372→		t.root = n
   373→	}
   374→	return nil
   375→}
