    28→// preimageStore wraps the methods of a backing store for reading and writing
    29→// trie node preimages.
    30→type preimageStore interface {
    31→	// Preimage retrieves the preimage of the specified hash.
    32→	Preimage(hash common.Hash) []byte
    33→
    34→	// InsertPreimage commits a set of preimages along with their hashes.
    35→	InsertPreimage(preimages map[common.Hash][]byte)
    36→
    37→	// PreimageEnabled returns true if the preimage store is enabled.
    38→	PreimageEnabled() bool
    39→}
    40→
    41→// SecureTrie is the old name of StateTrie.
    42→// Deprecated: use StateTrie.
    43→type SecureTrie = StateTrie
    44→
    45→// NewSecure creates a new StateTrie.
    46→// Deprecated: use NewStateTrie.
    47→func NewSecure(stateRoot common.Hash, owner common.Hash, root common.Hash, db database.NodeDatabase) (*SecureTrie, error) {
    48→	id := &ID{
    49→		StateRoot: stateRoot,
    50→		Owner:     owner,
    51→		Root:      root,
    52→	}
    53→	return NewStateTrie(id, db)
    54→}
    55→
    56→// StateTrie wraps a trie with key hashing. In a stateTrie trie, all
    57→// access operations hash the key using keccak256. This prevents
    58→// calling code from creating long chains of nodes that
    59→// increase the access time.
    60→//
    61→// Contrary to a regular trie, a StateTrie can only be created with
    62→// New and must have an attached database. The database also stores
    63→// the preimage of each key if preimage recording is enabled.
    64→//
    65→// StateTrie is not safe for concurrent use.
    66→type StateTrie struct {
    67→	trie        Trie
    68→	db          database.NodeDatabase
    69→	preimages   preimageStore
    70→	secKeyCache map[common.Hash][]byte
    71→}
    72→
    73→// NewStateTrie creates a trie with an existing root node from a backing database.
    74→//
    75→// If root is the zero hash or the sha3 hash of an empty string, the
    76→// trie is initially empty. Otherwise, New will panic if db is nil
    77→// and returns MissingNodeError if the root node cannot be found.
    78→func NewStateTrie(id *ID, db database.NodeDatabase) (*StateTrie, error) {
    79→	if db == nil {
    80→		panic("trie.NewStateTrie called without a database")
    81→	}
    82→	trie, err := New(id, db)
    83→	if err != nil {
    84→		return nil, err
    85→	}
    86→	tr := &StateTrie{
    87→		trie:        *trie,
    88→		db:          db,
    89→		secKeyCache: make(map[common.Hash][]byte),
    90→	}
    91→
    92→	// link the preimage store if it's supported
    93→	if preimages, ok := db.(preimageStore); ok && preimages.PreimageEnabled() {
    94→		tr.preimages = preimages
    95→	}
    96→	return tr, nil
    97→}
    98→
    99→// MustGet returns the value for key stored in the trie.
   100→// The value bytes must not be modified by the caller.
   101→//
   102→// This function will omit any encountered error but just
   103→// print out an error message.
   104→func (t *StateTrie) MustGet(key []byte) []byte {
   105→	return t.trie.MustGet(crypto.Keccak256(key))
   106→}
   107→
   108→// GetAccount attempts to retrieve an account with provided account address.
   109→// If the specified account is not in the trie, nil will be returned.
   110→// If a trie node is not found in the database, a MissingNodeError is returned.
   111→func (t *StateTrie) GetAccount(address common.Address) (*types.StateAccount, error) {
   112→	res, err := t.trie.Get(crypto.Keccak256(address.Bytes()))
   113→	if res == nil || err != nil {
   114→		return nil, err
   115→	}
   116→	ret := new(types.StateAccount)
   117→	err = rlp.DecodeBytes(res, ret)
   118→	return ret, err
   119→}
   120→
   121→// GetAccountByHash does the same thing as GetAccount, however it expects an
   122→// account hash that is the hash of address. This constitutes an abstraction
   123→// leak, since the client code needs to know the key format.
   124→func (t *StateTrie) GetAccountByHash(addrHash common.Hash) (*types.StateAccount, error) {
   125→	res, err := t.trie.Get(addrHash.Bytes())
   126→	if res == nil || err != nil {
   127→		return nil, err
   128→	}
   129→	ret := new(types.StateAccount)
   130→	err = rlp.DecodeBytes(res, ret)
   131→	return ret, err
   132→}
   133→
   134→// PrefetchAccount attempts to resolve specific accounts from the database
   135→// to accelerate subsequent trie operations.
   136→func (t *StateTrie) PrefetchAccount(addresses []common.Address) error {
   137→	var keys [][]byte
   138→	for _, addr := range addresses {
   139→		keys = append(keys, crypto.Keccak256(addr.Bytes()))
   140→	}
   141→	return t.trie.Prefetch(keys)
   142→}
   143→
   144→// GetStorage attempts to retrieve a storage slot with provided account address
   145→// and slot key. The value bytes must not be modified by the caller.
   146→// If the specified storage slot is not in the trie, nil will be returned.
   147→// If a trie node is not found in the database, a MissingNodeError is returned.
   148→func (t *StateTrie) GetStorage(_ common.Address, key []byte) ([]byte, error) {
   149→	enc, err := t.trie.Get(crypto.Keccak256(key))
   150→	if err != nil || len(enc) == 0 {
   151→		return nil, err
   152→	}
   153→	_, content, _, err := rlp.Split(enc)
   154→	return content, err
   155→}
   156→
   157→// PrefetchStorage attempts to resolve specific storage slots from the database
   158→// to accelerate subsequent trie operations.
   159→func (t *StateTrie) PrefetchStorage(_ common.Address, keys [][]byte) error {
   160→	var keylist [][]byte
   161→	for _, key := range keys {
   162→		keylist = append(keylist, crypto.Keccak256(key))
   163→	}
   164→	return t.trie.Prefetch(keylist)
   165→}
   166→
   167→// GetNode attempts to retrieve a trie node by compact-encoded path. It is not
   168→// possible to use keybyte-encoding as the path might contain odd nibbles.
   169→// If the specified trie node is not in the trie, nil will be returned.
   170→// If a trie node is not found in the database, a MissingNodeError is returned.
   171→func (t *StateTrie) GetNode(path []byte) ([]byte, int, error) {
   172→	return t.trie.GetNode(path)
   173→}
   174→
   175→// MustUpdate associates key with value in the trie. Subsequent calls to
   176→// Get will return value. If value has length zero, any existing value
   177→// is deleted from the trie and calls to Get will return nil.
   178→//
   179→// The value bytes must not be modified by the caller while they are
   180→// stored in the trie.
   181→//
   182→// This function will omit any encountered error but just print out an
   183→// error message.
   184→func (t *StateTrie) MustUpdate(key, value []byte) {
   185→	hk := crypto.Keccak256(key)
   186→	t.trie.MustUpdate(hk, value)
   187→	if t.preimages != nil {
   188→		t.secKeyCache[common.Hash(hk)] = common.CopyBytes(key)
   189→	}
   190→}
   191→
   192→// UpdateStorage associates key with value in the trie. Subsequent calls to
   193→// Get will return value. If value has length zero, any existing value
   194→// is deleted from the trie and calls to Get will return nil.
   195→//
   196→// The value bytes must not be modified by the caller while they are
   197→// stored in the trie.
   198→//
