    71→// EncodeRLP encodes a full node into the consensus RLP format.
    72→func (n *fullNode) EncodeRLP(w io.Writer) error {
    73→	eb := rlp.NewEncoderBuffer(w)
    74→	n.encode(eb)
    75→	return eb.Flush()
    76→}
    77→
    78→// nodeFlag contains caching-related metadata about a node.
    79→type nodeFlag struct {
    80→	hash  hashNode // cached hash of the node (may be nil)
    81→	dirty bool     // whether the node has changes that must be written to the database
    82→}
    83→
    84→func (n nodeFlag) copy() nodeFlag {
    85→	return nodeFlag{
    86→		hash:  common.CopyBytes(n.hash),
    87→		dirty: n.dirty,
    88→	}
    89→}
    90→
    91→func (n *fullNode) cache() (hashNode, bool)  { return n.flags.hash, n.flags.dirty }
    92→func (n *shortNode) cache() (hashNode, bool) { return n.flags.hash, n.flags.dirty }
    93→func (n hashNode) cache() (hashNode, bool)   { return nil, true }
    94→func (n valueNode) cache() (hashNode, bool)  { return nil, true }
    95→
    96→// Pretty printing.
    97→func (n *fullNode) String() string  { return n.fstring("") }
    98→func (n *shortNode) String() string { return n.fstring("") }
    99→func (n hashNode) String() string   { return n.fstring("") }
   100→func (n valueNode) String() string  { return n.fstring("") }
   101→
   102→func (n *fullNode) fstring(ind string) string {
   103→	resp := fmt.Sprintf("[\n%s  ", ind)
   104→	for i, node := range &n.Children {
   105→		if node == nil {
   106→			resp += fmt.Sprintf("%s: <nil> ", indices[i])
   107→		} else {
   108→			resp += fmt.Sprintf("%s: %v", indices[i], node.fstring(ind+"  "))
   109→		}
   110→	}
   111→	return resp + fmt.Sprintf("\n%s] ", ind)
   112→}
   113→
   114→func (n *shortNode) fstring(ind string) string {
   115→	return fmt.Sprintf("{%x: %v} ", n.Key, n.Val.fstring(ind+"  "))
   116→}
   117→func (n hashNode) fstring(ind string) string {
   118→	return fmt.Sprintf("<%x> ", []byte(n))
   119→}
   120→func (n valueNode) fstring(ind string) string {
   121→	return fmt.Sprintf("%x ", []byte(n))
   122→}
   123→
   124→// mustDecodeNode is a wrapper of decodeNode and panic if any error is encountered.
   125→func mustDecodeNode(hash, buf []byte) node {
   126→	n, err := decodeNode(hash, buf)
   127→	if err != nil {
   128→		panic(fmt.Sprintf("node %x: %v", hash, err))
   129→	}
   130→	return n
   131→}
   132→
   133→// mustDecodeNodeUnsafe is a wrapper of decodeNodeUnsafe and panic if any error is
   134→// encountered.
   135→func mustDecodeNodeUnsafe(hash, buf []byte) node {
   136→	n, err := decodeNodeUnsafe(hash, buf)
   137→	if err != nil {
   138→		panic(fmt.Sprintf("node %x: %v", hash, err))
   139→	}
   140→	return n
   141→}
   142→
   143→// decodeNode parses the RLP encoding of a trie node. It will deep-copy the passed
   144→// byte slice for decoding, so it's safe to modify the byte slice afterwards. The-
   145→// decode performance of this function is not optimal, but it is suitable for most
   146→// scenarios with low performance requirements and hard to determine whether the
   147→// byte slice be modified or not.
   148→func decodeNode(hash, buf []byte) (node, error) {
   149→	return decodeNodeUnsafe(hash, common.CopyBytes(buf))
   150→}
   151→
   152→// decodeNodeUnsafe parses the RLP encoding of a trie node. The passed byte slice
   153→// will be directly referenced by node without bytes deep copy, so the input MUST
   154→// not be changed after.
   155→func decodeNodeUnsafe(hash, buf []byte) (node, error) {
   156→	if len(buf) == 0 {
   157→		return nil, io.ErrUnexpectedEOF
   158→	}
   159→	elems, _, err := rlp.SplitList(buf)
   160→	if err != nil {
   161→		return nil, fmt.Errorf("decode error: %v", err)
   162→	}
   163→	switch c, _ := rlp.CountValues(elems); c {
   164→	case 2:
   165→		n, err := decodeShort(hash, elems)
   166→		return n, wrapError(err, "short")
   167→	case 17:
   168→		n, err := decodeFull(hash, elems)
   169→		return n, wrapError(err, "full")
   170→	default:
   171→		return nil, fmt.Errorf("invalid number of list elements: %v", c)
   172→	}
   173→}
   174→
   175→func decodeShort(hash, elems []byte) (node, error) {
   176→	kbuf, rest, err := rlp.SplitString(elems)
   177→	if err != nil {
   178→		return nil, err
   179→	}
   180→	flag := nodeFlag{hash: hash}
   181→	key := compactToHex(kbuf)
   182→	if hasTerm(key) {
   183→		// value node
   184→		val, _, err := rlp.SplitString(rest)
   185→		if err != nil {
   186→			return nil, fmt.Errorf("invalid value node: %v", err)
   187→		}
   188→		return &shortNode{key, valueNode(val), flag}, nil
   189→	}
   190→	r, _, err := decodeRef(rest)
   191→	if err != nil {
   192→		return nil, wrapError(err, "val")
   193→	}
   194→	return &shortNode{key, r, flag}, nil
   195→}
   196→
   197→func decodeFull(hash, elems []byte) (*fullNode, error) {
   198→	n := &fullNode{flags: nodeFlag{hash: hash}}
   199→	for i := 0; i < 16; i++ {
   200→		cld, rest, err := decodeRef(elems)
   201→		if err != nil {
   202→			return n, wrapError(err, fmt.Sprintf("[%d]", i))
